function claim(claimId, patientRef, serviceDate, procedureCode, amount) {
  return {
    claimId: claimId,
    patientRef: patientRef,
    serviceDate: serviceDate,
    procedureCode: procedureCode,
    amount: amount
  };
}

function normalize(result) {
  var groups = [];
  var i;
  assert.deepEqual(Object.keys(result).sort(), ["groups"]);
  for (i = 0; i < result.groups.length; i = i + 1) {
    var g = result.groups[i];
    assert.deepEqual(Object.keys(g).sort(), ["amount", "claimIds", "patientRef", "procedureCode", "serviceDate"]);
    groups.push({
      claimIds: g.claimIds.slice().sort(),
      patientRef: g.patientRef,
      serviceDate: g.serviceDate,
      procedureCode: g.procedureCode,
      amount: g.amount
    });
  }
  groups.sort(function (a, b) {
    var as = a.serviceDate + "|" + a.procedureCode + "|" + a.patientRef + "|" + a.amount + "|" + a.claimIds.join(",");
    var bs = b.serviceDate + "|" + b.procedureCode + "|" + b.patientRef + "|" + b.amount + "|" + b.claimIds.join(",");
    if (as < bs) return -1;
    if (as > bs) return 1;
    return 0;
  });
  return groups;
}

test("flags two claims that look the same as one group even when claim ids differ", function () {
  var claims = [
    claim("C-1", "P-001", "2024-03-05", "99213", 120.00),
    claim("C-2", "P-001", "2024-03-05", "99213", 120.00)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), [
    {
      claimIds: ["C-1", "C-2"],
      patientRef: "P-001",
      serviceDate: "2024-03-05",
      procedureCode: "99213",
      amount: 120.00
    }
  ]);
});

test("does not flag claims when the amount is not an exact match", function () {
  var claims = [
    claim("C-3", "P-002", "2024-03-05", "99213", 120.00),
    claim("C-4", "P-002", "2024-03-05", "99213", 125.00)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), []);
});

test("puts three matching claims in one group rather than three pairs", function () {
  var claims = [
    claim("C-5", "P-003", "2024-03-06", "99214", 80.00),
    claim("C-6", "P-003", "2024-03-06", "99214", 80.00),
    claim("C-7", "P-003", "2024-03-06", "99214", 80.00)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), [
    {
      claimIds: ["C-5", "C-6", "C-7"],
      patientRef: "P-003",
      serviceDate: "2024-03-06",
      procedureCode: "99214",
      amount: 80.00
    }
  ]);
});

test("does not flag identical claims passed in different batch calls", function () {
  var batchA = [claim("C-8", "P-004", "2024-03-07", "99213", 120.00)];
  var batchB = [claim("C-9", "P-004", "2024-03-07", "99213", 120.00)];
  assert.deepEqual(normalize(code.findDuplicateGroups(batchA)), []);
  assert.deepEqual(normalize(code.findDuplicateGroups(batchB)), []);
});

test("returns no group for an empty batch", function () {
  assert.deepEqual(normalize(code.findDuplicateGroups([])), []);
});

test("returns no group for a single claim", function () {
  var claims = [claim("C-10", "P-005", "2024-01-01", "99213", 0)];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), []);
});

test("flags two groups and leaves the unmatched claim off the review list", function () {
  var claims = [
    claim("C-F1", "P-100", "2024-04-30", "99213", 30.00),
    claim("C-U", "P-101", "2024-04-30", "99213", 30.00),
    claim("C-M1", "P-102", "2024-05-01", "99215", 1.00),
    claim("C-M2", "P-102", "2024-05-01", "99215", 1.00),
    claim("C-F2", "P-100", "2024-04-30", "99213", 30.00)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), [
    {
      claimIds: ["C-F1", "C-F2"],
      patientRef: "P-100",
      serviceDate: "2024-04-30",
      procedureCode: "99213",
      amount: 30.00
    },
    {
      claimIds: ["C-M1", "C-M2"],
      patientRef: "P-102",
      serviceDate: "2024-05-01",
      procedureCode: "99215",
      amount: 1.00
    }
  ]);
});

test("flags only the exact leap day pair and leaves near matches unlisted", function () {
  var claims = [
    claim("C-B", "P-041", "2024-02-29", "99213", 10.00),
    claim("C-A1", "P-040", "2024-02-29", "99213", 10.00),
    claim("C-C", "P-040", "2024-03-01", "99213", 10.00),
    claim("C-A2", "P-040", "2024-02-29", "99213", 10.00),
    claim("C-D", "P-040", "2024-02-29", "99214", 10.00),
    claim("C-E", "P-040", "2024-02-29", "99213", 10.01)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), [
    {
      claimIds: ["C-A1", "C-A2"],
      patientRef: "P-040",
      serviceDate: "2024-02-29",
      procedureCode: "99213",
      amount: 10.00
    }
  ]);
});

