});

test("flags an exact zero amount pair and leaves the amount one step away unlisted", function () {
  var claims = [
    claim("Z1", "P-Z", "2024-07-01", "99213", 0),
    claim("Z3", "P-Z", "2024-07-01", "99213", 1),
    claim("Z2", "P-Z", "2024-07-01", "99213", 0)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), [
    {
      claimIds: ["Z1", "Z2"],
      patientRef: "P-Z",
      serviceDate: "2024-07-01",
      procedureCode: "99213",
      amount: 0
    }
  ]);
});

test("does not attach a later batch claim to an earlier matching group", function () {
  var call1 = [
    claim("C-20", "P-200", "2024-12-01", "99213", 15.00),
    claim("C-21", "P-200", "2024-12-01", "99213", 15.00)
  ];
  var call2 = [claim("C-22", "P-200", "2024-12-01", "99213", 15.00)];
  assert.deepEqual(normalize(code.findDuplicateGroups(call1)), [
    {
      claimIds: ["C-20", "C-21"],
      patientRef: "P-200",
      serviceDate: "2024-12-01",
      procedureCode: "99213",
      amount: 15.00
    }
  ]);
  assert.deepEqual(normalize(code.findDuplicateGroups(call2)), []);
});

test("flags one group of three and leaves a near amount and a different patient unlisted", function () {
  var claims = [
    claim("T1", "P-T", "2024-08-31", "99213", 8.00),
    claim("U1", "P-T", "2024-08-31", "99213", 8.01),
    claim("T2", "P-T", "2024-08-31", "99213", 8.00),
    claim("U2", "P-U", "2024-08-31", "99213", 8.00),
    claim("T3", "P-T", "2024-08-31", "99213", 8.00)
  ];
  assert.deepEqual(normalize(code.findDuplicateGroups(claims)), [
    {
      claimIds: ["T1", "T2", "T3"],
      patientRef: "P-T",
      serviceDate: "2024-08-31",
      procedureCode: "99213",
      amount: 8.00
    }
  ]);
});

test("throws unknown field note when the last claim has an extra field", function () {
  var claims = [
    claim("E1", "P-E", "2024-06-15", "99213", 5.00),
    claim("E2", "P-E", "2024-06-15", "99213", 5.00),
    {
      claimId: "E3",
      patientRef: "P-E",
      serviceDate: "2024-06-15",
      procedureCode: "99213",
      amount: 5.00,
      note: "note"
    }
  ];
  assert.throws(function () {
    code.findDuplicateGroups(claims);
  }, /^unknown field: note$/);
});
